import{f as o,J as n,o as i,c as l,k as t,a,b as r,w as d,K as h,a7 as c,a6 as g}from"./chunks/framework.Dd1qhYRL.js";const v=JSON.parse('{"title":"The modeling skill","description":"/ignatius-modeling writes ignatius entities and data flow diagrams by asking one question at a time, runs ignatius validate on each file, and ends every session with a change note you review and approve.","frontmatter":{"title":"The modeling skill","description":"/ignatius-modeling writes ignatius entities and data flow diagrams by asking one question at a time, runs ignatius validate on each file, and ends every session with a change note you review and approve."},"headers":[],"relativePath":"modeling/modeling-skill.md","filePath":"modeling/modeling-skill.md"}'),m={name:"modeling/modeling-skill.md"};function u(p,e,k,w,b,f){const s=n("Mermaid");return i(),l("div",null,[e[1]||(e[1]=t("h1",{id:"the-modeling-skill",tabindex:"-1"},[a("The modeling skill "),t("a",{class:"header-anchor",href:"#the-modeling-skill","aria-label":"Permalink to “The modeling skill”"},"​")],-1)),e[2]||(e[2]=t("p",null,[t("code",null,"/ignatius-modeling"),a(" is a Claude Code skill that writes ignatius entity and flow files by asking you one question at a time.")],-1)),e[3]||(e[3]=t("p",null,"One session asks, writes, validates, and then waits for you to approve:",-1)),(i(),r(c,null,{default:d(()=>[h(s,{id:"mermaid-9",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20participant%20You%0A%20%20%20%20participant%20Skill%0A%20%20%20%20participant%20Files%20as%20model%20files%0A%20%20%20%20participant%20Validate%20as%20ignatius%20validate%0A%20%20%20%20You-%3E%3ESkill%3A%20%2Fignatius-modeling%20entity%0A%20%20%20%20loop%20each%20step%0A%20%20%20%20%20%20%20%20Skill-%3E%3EYou%3A%20one%20question%0A%20%20%20%20%20%20%20%20You-%3E%3ESkill%3A%20answer%0A%20%20%20%20end%0A%20%20%20%20Skill-%3E%3EFiles%3A%20write%20the%20entity%20file%0A%20%20%20%20Skill-%3E%3EValidate%3A%20check%20the%20model%20folder%0A%20%20%20%20Validate--%3E%3ESkill%3A%20findings%2C%20up%20to%205%20attempts%0A%20%20%20%20Skill-%3E%3EFiles%3A%20write%20.ignatius%2Fchanges%2Fslug.md%0A%20%20%20%20You-%3E%3EFiles%3A%20ignatius%20serve%2C%20read%20the%20changes%0A%20%20%20%20You-%3E%3EFiles%3A%20ignatius%20approve%0A"})]),fallback:d(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=g('<p>The skill needs Claude Code and the <code>ignatius</code> binary on your <code>$PATH</code> (<a href="/download.html">Download</a>). Install the skill into the current project, or add <code>-g</code> for every project:</p><div class="language-bash"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npx</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> skills</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> add</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> https://github.com/noormdev/ignatius</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --skill</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ignatius-modeling</span></span></code></pre></div><h2 id="which-mode-do-i-run" tabindex="-1">Which mode do I run? <a class="header-anchor" href="#which-mode-do-i-run" aria-label="Permalink to “Which mode do I run?”">​</a></h2><table tabindex="0"><thead><tr><th>Invocation</th><th>Use it to</th></tr></thead><tbody><tr><td><code>/ignatius-modeling entity</code></td><td>Add one entity</td></tr><tr><td><code>/ignatius-modeling model</code></td><td>Bootstrap <code>ignatius.yml</code>, group files, and folders</td></tr><tr><td><code>/ignatius-modeling flow</code></td><td>Author a <a href="/modeling/data-flows.html">data flow diagram</a> when you can already name your processes</td></tr><tr><td><code>/ignatius-modeling discover</code></td><td>Work out entities and flows from how the business runs. With a real database, schema dump, codebase, or API, it reads that instead of interviewing you</td></tr><tr><td><code>/ignatius-modeling</code></td><td>Asks which mode</td></tr></tbody></table><p>Every entity gets example rows and every process gets input and output examples, because concrete rows expose wrong rules that pass every structural check. The skill picks <code>key-inherited</code> or <code>orm-oriented</code> for each new entity from the keys you already have; see <a href="/modeling/entities.html">the two key conventions</a>. To point <code>discover</code> at a live database, see <a href="/modeling/reverse-engineering.html">Reverse-engineering</a>.</p><h2 id="what-does-validation-catch" tabindex="-1">What does validation catch? <a class="header-anchor" href="#what-does-validation-catch" aria-label="Permalink to “What does validation catch?”">​</a></h2><p>After each write the skill runs <code>ignatius validate &lt;model-root&gt;</code>, reports each finding with a fix hint, and asks whether to revise. It stops after five attempts.</p><table tabindex="0"><thead><tr><th>Check</th><th>Done by</th></tr></thead><tbody><tr><td>Unknown targets, dangling foreign-key columns, missing discriminators, unknown columns in flow contracts, unbalanced decompositions</td><td><code>ignatius validate</code></td></tr><tr><td>Example rows with a key that is not a column</td><td>Only <code>ignatius serve</code> shows it. <code>validate</code> never prints that rule, so the skill reads the rows back</td></tr><tr><td>Each predicate reads as a true sentence both ways, and the body states the purpose and rules</td><td>The skill&#39;s self-check, then you</td></tr></tbody></table><h2 id="how-do-i-review-what-it-changed" tabindex="-1">How do I review what it changed? <a class="header-anchor" href="#how-do-i-review-what-it-changed" aria-label="Permalink to “How do I review what it changed?”">​</a></h2><p>Every session that changes model files ends with one change note, <code>.ignatius/changes/&lt;slug&gt;.md</code>. It names the entities, columns, diagrams, and nodes the session touched and says why. <code>ignatius serve</code> shows the edit as highlights beside the note. <code>ignatius approve</code> accepts it.</p><p>Before its first write, the skill checks for a baseline so that the edit shows as a change:</p><table tabindex="0"><thead><tr><th><code>.ignatius/baseline.json</code></th><th><code>.ignatius/changes/</code></th><th>The skill</th></tr></thead><tbody><tr><td>valid</td><td>any</td><td>edits as usual</td></tr><tr><td>missing or invalid</td><td>empty</td><td>runs <code>ignatius approve</code>, then edits</td></tr><tr><td>missing or invalid</td><td>holds notes</td><td>stops and asks you to approve the notes or restore the baseline</td></tr></tbody></table><p>The skill never runs <code>approve</code> after editing. Accepting the edit is your step. The <code>model</code> mode writes no note, and a model it creates gets a <code>.gitignore</code> containing <code>.ignatius/</code>. The note format is in <a href="https://github.com/noormdev/ignatius/blob/main/docs/guides/change-review.md" target="_blank" rel="noreferrer">Change review</a>.</p><h2 id="what-bites" tabindex="-1">What bites <a class="header-anchor" href="#what-bites" aria-label="Permalink to “What bites”">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause</th><th>Fix</th></tr></thead><tbody><tr><td>The skill stops before its first write</td><td><code>.ignatius/changes/</code> holds notes and there is no baseline</td><td>Read the notes, run <code>ignatius approve</code>, then continue</td></tr><tr><td>A change shows as <code>unexplained</code></td><td>The note does not name that entity, column, diagram, or node</td><td>Add the name to the note</td></tr><tr><td>A note shows <code>named but unchanged</code></td><td>The note names an entity, column, diagram, or node that did not change</td><td>Remove the name, or make the change</td></tr><tr><td>A note you wanted is gone</td><td><code>ignatius approve</code> deletes every note</td><td>Copy anything worth keeping into the entity or flow body first</td></tr></tbody></table><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to “Next”">​</a></h2><ul><li><a href="/modeling/entities.html">Entities and key inheritance</a>: the format the skill writes</li><li><a href="/modeling/data-flows.html">Data flows</a>: the diagram format</li><li><a href="/modeling/model-to-sql.html">From model to SQL</a>: hand the validated model to an agent that writes the DDL</li><li><a href="/modeling/best-practices.html">Best practices</a>: review what the skill produces</li></ul>',17))])}const A=o(m,[["render",u]]);export{v as __pageData,A as default};
